// /app/app/dgn-reels.js — off-chain derivation of Degenerette house reels.
//
// WHY THIS EXISTS: a Degenerette bet of N spins rolls a DIFFERENT house ticket
// every spin, but the chain only publishes the first one. DegeneretteResolved
// carries `resultTraits` for spin 0 only, and its `spins` bytes carry each
// spin's player lanes and a score byte (score | house wilds << 4) — never the
// house reel it played against. So a UI that wants to SHOW spin 3's reel has to
// re-derive it exactly the way the contract did. Placed bets are ETH (0) or
// FLIP (1) only; dgnRollSpin is the port of _rollSpin for box/foil spins,
// including the WWXRP rig.
//
// Ported from degenerus-audit/contracts. Derivation is checked against the
// emitted first house ticket and every per-card score and wild count before
// revealing results. Lanes are Degenerette lanes (bit 6 wild; byte position =
// quadrant), shared with dgn-traits.js dgnUnpackTicket.
//
// Decoding (lanes → symbols) lives in dgn-traits.js. Do not add a decoder here.

import { keccak256 } from 'ethers';

// DegenerusGameDegeneretteModule.sol
const QUICK_PLAY_SALT = 0x51;               // 'Q'
const PLAYER_TICKET_TAG = 0x446567656e506c61796572n; // "DegenPlayer"
const HERO_PICK_TAG = 0x446567656e4865726fn;  // "DegenHero"
const WWXRP_RIG_SALT = 0x52494721n;         // "RIG!"
const RANDOM_HERO = 32;
const RECORD_SPIN_TAG = 0x5265636f7264n;     // "Record"
const BOX_BET_ID_SENTINEL = 1n << 63n;
const BOX_SPIN_TYPE_RECORD = 3n;
const BOX_BET_ID_ENTROPY_MASK = (1n << 60n) - 1n;
const CURRENCY_WWXRP = 3;

function _big(v) {
  try { return BigInt(v ?? 0); } catch (_e) { return 0n; }
}

/** Big-endian 32-byte write of a uint256 into `buf` at `off`. */
function _writeWord(buf, off, word) {
  let w = word;
  for (let i = 31; i >= 0; i--) {
    buf[off + i] = Number(w & 0xFFn);
    w >>= 8n;
  }
}

/**
 * The per-spin result seed. Byte-identical preimage to the module's assembly:
 * spin 0 hashes 37 bytes (no spinIdx), later spins hash 38.
 *
 * @param {bigint|string|number} rngWord lootboxRngWordByIndex[index]
 * @param {number} index the bet's lootbox RNG index (uint32 on the wire)
 * @param {number} spinIdx 0-based spin
 * @returns {bigint}
 */
export function dgnResultSeed(rngWord, index, spinIdx) {
  return _hash3(8n, _big(rngWord), BigInt(spinIdx));
}

/** EntropyLib.hash2 — keccak of two words in scratch space. */
function _hash2(a, b) {
  const buf = new Uint8Array(64);
  _writeWord(buf, 0, a);
  _writeWord(buf, 32, b);
  return _big(keccak256(buf));
}

function _hash3(a, b, c) {
  const buf = new Uint8Array(96);
  [a, b, c].forEach((word, index) => _writeWord(buf, index * 32, word));
  return _big(keccak256(buf));
}

/** EntropyLib.hash4 — keccak of four uint256 words. */
function _hash4(a, b, c, d) {
  const buf = new Uint8Array(128);
  [a, b, c, d].forEach((word, index) => _writeWord(buf, index * 32, word));
  return _big(keccak256(buf));
}

/** The record bounty retains the placed champion; verify its parent seed. */
export function dgnRecordBountyHeroQuadrants({
  rngWord, parentBetId, player, playerId, symbol, boxBetId = null, spinCount = 3,
} = {}) {
  let seed;
  try {
    const word = BigInt(rngWord ?? 0);
    const parent = BigInt(parentBetId ?? 0);
    if (!word || parent <= 0n || (!Number.isInteger(Number(playerId)) || Number(playerId) <= 0 || Number(playerId) > 0xffffffff)
      || !Number.isInteger(symbol) || symbol < 0 || symbol > 31) return null;
    seed = _hash3(10n, word, parent);
    if (boxBetId != null && BigInt(boxBetId) !== (BOX_BET_ID_SENTINEL
      | (BOX_SPIN_TYPE_RECORD << 60n) | (seed & BOX_BET_ID_ENTROPY_MASK))) return null;
  } catch (_) { return null; }
  const count = Math.max(0, Math.min(3, Math.trunc(Number(spinCount) || 0)));
  return Array(count).fill(symbol >> 3);
}

/**
 * DegenerusTraitUtils.packedTraitsDegeneretteOrdinary — a 256-bit word → the
 * packed uint32 lanes. Lane q (byte q) is [0 | 0 | color | symbol] with the
 * color from bits 64q..64q+2 and the symbol from bits 64q+32..64q+34.
 *
 * @param {bigint|string|number} rand
 * @returns {number} uint32
 */
export function dgnOrdinaryLanes(rand) {
  const word = _big(rand);
  let t = 0;
  for (let q = 0; q < 4; q++) {
    const lane = word >> BigInt(64 * q);
    const color = Number(lane & 7n);
    const symbol = Number((lane >> 32n) & 7n);
    t |= ((color << 3) | symbol) << (q * 8);
  }
  return t >>> 0;
}

/**
 * DegenerusTraitUtils.packedTraitsDegenerette — house lanes: as the ordinary
 * lanes, but lane q is WILD (0x40 | symbol) when bits 64q+3..64q+6 are zero.
 *
 * @param {bigint|string|number} rand
 * @returns {number} uint32
 */
export function dgnHouseLanes(rand) {
  const word = _big(rand);
  let t = dgnOrdinaryLanes(word);
  for (let q = 0; q < 4; q++) {
    if (((word >> BigInt(64 * q + 3)) & 0xFn) !== 0n) continue;
    const symbol = (t >>> (q * 8)) & 7;
    t = ((t & ~(0xFF << (q * 8))) | ((0x40 | symbol) << (q * 8))) >>> 0;
  }
  return t >>> 0;
}

/**
 * The spin's hero symbol (0..23): a placed bet's symbol, or for the internal
 * RANDOM_HERO sentinel (32) hash2(seed, HERO_PICK_TAG) % 24.
 */
export function dgnSpinSymbol(seed, symbol) {
  return Number(symbol) === RANDOM_HERO
    ? Number(_hash2(89n, _big(seed)) % 24n)
    : Number(symbol);
}

/**
 * DegeneretteModule._playerTicket — ordinary lanes from hash2(seed,
 * PLAYER_TICKET_TAG), with the hero lane (symbol >> 3) replaced by the wild
 * lane 0x40 | (symbol & 7). The player always holds exactly one wild.
 */
export function dgnPlayerTicket(seed, symbol) {
  const t = dgnOrdinaryLanes(_hash2(91n, _big(seed)));
  const shift = (Number(symbol) >> 3) * 8;
  return (((t & ~(0xFF << shift)) | ((0x40 | (Number(symbol) & 7)) << shift)) >>> 0);
}

/** The matched-lane view of one player/house lane pair: symbol hit, color points. */
function _lanePoints(pq, rq) {
  const pWild = (pq & 0x40) !== 0;
  const rWild = (rq & 0x40) !== 0;
  const color = pWild && rWild ? 2 : pWild || rWild ? 1 : (((pq >> 3) & 7) === ((rq >> 3) & 7) ? 1 : 0);
  return { symbol: (pq & 7) === (rq & 7) ? 1 : 0, color, rWild };
}

/**
 * Module _score — per lane one point for an equal symbol, and for color: both
 * wild 2, one wild 1, else equal colors 1. `wilds` counts the HOUSE's wild
 * lanes (the player's own wild never counts). Score 1..9.
 *
 * @returns {{score: number, wilds: number}}
 */
export function dgnScoreWilds(playerTraits, resultTraits) {
  const p = Number(playerTraits) >>> 0;
  const r = Number(resultTraits) >>> 0;
  let score = 0;
  let wilds = 0;
  for (let q = 0; q < 4; q++) {
    const lane = _lanePoints((p >>> (q * 8)) & 0xFF, (r >>> (q * 8)) & 0xFF);
    score += lane.symbol + lane.color;
    if (lane.rWild) wilds++;
  }
  return { score, wilds };
}

/** Score S of a player/house ticket pair. */
export function dgnScore(playerTraits, resultTraits) {
  return dgnScoreWilds(playerTraits, resultTraits).score;
}

/** Number of wild lanes on a house ticket. */
export function dgnWilds(resultTraits) {
  const r = Number(resultTraits) >>> 0;
  let wilds = 0;
  for (let q = 0; q < 4; q++) if ((r >>> (q * 8)) & 0x40) wilds++;
  return wilds;
}

/**
 * The WWXRP reel rig (box/foil WWXRP spins only). With rigSeed % 20 == 0,
 * score S >= 3 and matched axes M = S - (house hero lane wild ? 1 : 0) <= 6,
 * one eligible axis (color of a lane where neither side is wild and the colors
 * differ; symbol of a non-hero lane that differs; walking q = 0..3, color
 * before symbol) is copied from the player into the house ticket.
 *
 * @returns {{traits: number, helped: boolean}}
 */
export function dgnRigWwxrpResult(playerTraits, resultTraits, heroQuadrant, rigSeed) {
  const p = Number(playerTraits) >>> 0;
  const r = Number(resultTraits) >>> 0;
  const hero = Number(heroQuadrant) & 3;
  const seed = _big(rigSeed);
  if (seed % 20n !== 0n) return { traits: r, helped: false };
  const score = dgnScore(p, r);
  const matched = score - ((r >>> (hero * 8 + 6)) & 1);
  if (score < 3 || matched > 6) return { traits: r, helped: false };
  const masks = [];
  for (let q = 0; q < 4; q++) {
    const pq = (p >>> (q * 8)) & 0xFF;
    const rq = (r >>> (q * 8)) & 0xFF;
    if (!((pq | rq) & 0x40) && ((pq >> 3) & 7) !== ((rq >> 3) & 7)) masks.push(0x38 << (q * 8));
    if (q !== hero && (pq & 7) !== (rq & 7)) masks.push(0x07 << (q * 8));
  }
  if (masks.length === 0) return { traits: r, helped: false };
  const mask = masks[Number(_hash2(94n, seed) % BigInt(masks.length))];
  return { traits: (((r & ~mask) | (p & mask)) >>> 0), helped: true };
}

/** The rigged house ticket alone (see dgnRigWwxrpResult). */
export function dgnRigWwxrp(playerTraits, resultTraits, heroQuadrant, rigSeed) {
  return dgnRigWwxrpResult(playerTraits, resultTraits, heroQuadrant, rigSeed).traits;
}

/**
 * DegeneretteModule._rollSpin — one spin from its seeds: the player ticket from
 * `seed`, the house lanes from `houseSeed`, and for WWXRP the 5% rig keyed by
 * hash2(seed, WWXRP_RIG_SALT).
 *
 * @param {{seed: bigint|string|number, houseSeed: bigint|string|number,
 *          symbol: number, currency?: number}} a
 * @returns {{hero: number, player: number, naturalHouse: number, house: number,
 *            helped: boolean, score: number, wilds: number}}
 */
export function dgnRollSpin({ seed, houseSeed, symbol, currency }) {
  const hero = dgnSpinSymbol(seed, symbol);
  const player = dgnPlayerTicket(seed, hero);
  const naturalHouse = dgnHouseLanes(houseSeed);
  let house = naturalHouse;
  let helped = false;
  if (Number(currency) === CURRENCY_WWXRP) {
    ({ traits: house, helped } = dgnRigWwxrpResult(
      player, naturalHouse, hero >> 3, _hash2(93n, _big(seed)),
    ));
  }
  const { score, wilds } = dgnScoreWilds(player, house);
  return { hero, player, naturalHouse, house, helped, score, wilds };
}

/**
 * One placed-bet spin's house reel. Placed bets are ETH or FLIP, which carry no
 * rig; the WWXRP spin is dgnRollSpin.
 *
 * @param {{rngWord: bigint|string|number, index: number, spinIdx: number}} a
 * @returns {number} uint32 packed house lanes
 */
export function dgnHouseTraits({ rngWord, index, spinIdx }) {
  return dgnHouseLanes(dgnResultSeed(_big(rngWord), index, spinIdx));
}

/**
 * The board behind a resolved bet: one row per spin, each with the reel that
 * spin actually played against.
 *
 * Self-checking. Two independent tells, both from data the chain published:
 *   - spin 0's derived reel must equal `resolvedResultTraits`;
 *   - each derived score must equal that spin's emitted `matches`.
 * Verification is per spin. A stale/malformed row is left blank without
 * erasing the independently verified later reels; `verified` remains the
 * all-rows summary bit for callers that need it.
 *
 * @param {{
 *   rngWord: bigint|string|number,
 *   index: number,
 *   resolvedResultTraits?: bigint|string|number,
 *   spins: Array<{spinIndex: bigint|number, playerTraits: bigint|number,
 *                 matches?: bigint|number, wilds?: bigint|number,
 *                 payout?: bigint|number}>,
 * }} args
 * @returns {{verified: boolean, reason: string|null,
 *            rows: Array<{spinIndex: number, playerTraits: number,
 *                         houseTraits: number|null, score: number,
 *                         payout: bigint}>}}
 */
export function dgnDeriveSpins({
  rngWord, index, resolvedResultTraits, spins,
} = {}) {
  const list = Array.isArray(spins) ? spins : [];
  const word = _big(rngWord);
  const rows = list
    .map((s) => ({
      spinIndex: Number(s?.spinIndex ?? 0),
      playerTraits: Number(s?.playerTraits ?? 0) >>> 0,
      matches: Number(s?.matches ?? 0),
      wilds: s?.wilds == null ? null : Number(s.wilds),
      payout: _big(s?.payout),
    }))
    .sort((a, b) => a.spinIndex - b.spinIndex);

  const fail = (reason) => ({
    verified: false,
    reason,
    rows: rows.map((r) => ({
      spinIndex: r.spinIndex,
      playerTraits: r.playerTraits,
      houseTraits: null,
      score: r.matches,
      payout: r.payout,
    })),
  });

  if (rows.length === 0) return fail('no per-card events');
  if (word === 0n) return fail('rng word unavailable');

  const derived = rows.map((r) => dgnHouseTraits({
    rngWord: word,
    index,
    spinIdx: r.spinIndex,
  }));

  const failures = [];
  const valid = derived.map(() => true);

  // Tell #1 — spin 0 against the chain's own published reel.
  const zeroAt = rows.findIndex((r) => r.spinIndex === 0);
  if (resolvedResultTraits != null && zeroAt >= 0) {
    const published = Number(_big(resolvedResultTraits)) >>> 0;
    if (published !== derived[zeroAt]) {
      valid[zeroAt] = false;
      failures.push('card 0 result mismatch');
    }
  }
  // Tell #2 — every score and wild count. Keep good later rows even if one
  // projection is bad.
  for (let i = 0; i < rows.length; i++) {
    const { score, wilds } = dgnScoreWilds(rows[i].playerTraits, derived[i]);
    if (score !== rows[i].matches || (rows[i].wilds != null && wilds !== rows[i].wilds)) {
      valid[i] = false;
      failures.push(`score mismatch on card ${rows[i].spinIndex + 1}`);
    }
  }

  return {
    verified: failures.length === 0,
    reason: failures.length > 0 ? failures.join('; ') : null,
    rows: rows.map((r, i) => ({
      spinIndex: r.spinIndex,
      playerTraits: r.playerTraits,
      houseTraits: valid[i] ? derived[i] : null,
      score: r.matches,
      payout: r.payout,
    })),
  };
}
